zGreatSCS = Canvas(scsApp, height='500', width='455')

bgZSc = ''
bcckgrnd = ''
colorCTc = ''

var1 = DoubleVar()
var2 = DoubleVar()
var3 = DoubleVar()

def colorRGB():
    global bgZSc, colorCTs
        
    colorRa = int(var1.get())
    colorGa = int(var2.get())
    colorBa = int(var3.get())
    colorAa = "{:#04x}" 
    colorRb = int(hex(colorRa), 16) 
    colorGb = int(hex(colorGa), 16)
    colorBb = int(hex(colorBa), 16)
    colorRab = colorAa.format(colorRb)
    colorGab = colorAa.format(colorGb)
    colorBab = colorAa.format(colorBb)
    colorRc = "".join(repr(colorRab).replace("0x", "").replace("'", ""))
    colorGc = "".join(repr(colorGab).replace("0x", "").replace("'", ""))
    colorBc = "".join(repr(colorBab).replace("0x", "").replace("'", ""))
    colorRd = colorRc
    colorGd = colorGc
    colorBd = colorBc
    colorCT = (colorRd, colorGd, colorBd)
    colorCTb = "".join(repr(colorCT).replace(",", "").replace("('", "").replace("' '", "").replace("')", ""))
    colorCTs = "#" + colorCTb
    bgZSc = colorCTs
        
    return

colorSlide1 = Scale(zGreatSCS, label="RED", orient=HORIZONTAL, from_=0, to=255, variable=var1)
colorSlide1.grid(row='0', column='0', sticky='NW')
colorSlide2 = Scale(zGreatSCS, label="GREEN", orient=HORIZONTAL, from_=0, to=255, variable=var2)
colorSlide2.grid(row='1', column='0', sticky='NW')
colorSlide3 = Scale(zGreatSCS, label="BLUE", orient=HORIZONTAL, from_=0, to=255, variable=var3)
colorSlide3.grid(row='2', column='0', sticky='NW')
colorSlide7 = Entry(zGreatSCS, textvariable=var1)
colorSlide7.grid(row='3', column='0', sticky='NW')
colorSlide8 = Entry(zGreatSCS, textvariable=var2)
colorSlide8.grid(row='4', column='0', sticky='NW')
colorSlide9 = Entry(zGreatSCS, textvariable=var3)
colorSlide9.grid(row='5', column='0', sticky='NW')
qButton = Button(zGreatSCS, text='Spec', width='3', height='2', command=colorRGB)
qButton.grid(row='0', column='1', sticky='NW')
var4 = DoubleVar()
var5 = DoubleVar()
var6 = DoubleVar()

def colorRGB2():
    global bcckgrnd, colorCTc
    
    colorRa = int(var4.get())
    colorGa = int(var5.get())
    colorBa = int(var6.get())
    colorAa = "{:#04x}"
    colorRb = int(hex(colorRa), 16)
    colorGb = int(hex(colorGa), 16)
    colorBb = int(hex(colorBa), 16)
    colorRab = colorAa.format(colorRb)
    colorGab = colorAa.format(colorGb)
    colorBab = colorAa.format(colorBb)
    colorRc = "".join(repr(colorRab).replace("0x", "").replace("'", ""))
    colorGc = "".join(repr(colorGab).replace("0x", "").replace("'", ""))
    colorBc = "".join(repr(colorBab).replace("0x", "").replace("'", ""))
    colorRd = colorRc
    colorGd = colorGc
    colorBd = colorBc
    colorCTa = (colorRd, colorGd, colorBd)
    colorCTb = "".join(repr(colorCTa).replace(",", "").replace("('", "").replace("' '", "").replace("')", ""))
    colorCTc = "#" + colorCTb
    bcckgrnd = colorCTc
    
    return

